@Component("kycRecord-entity-projector")
public class KycRecordEntityProjector implements EntityProjector<KycRecord>{
		
	// core constructor
	public KycRecordEntityProjector(ProjectorRegistry registry,
										KycRecordRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<KycRecord> getEntityClass() {
		return KycRecord.class;
	}

    /*
	 * Insert a KycRecord
	 * 
     * @param	entity KycRecord
     */
    public KycRecord create( KycRecord entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a KycRecord
	 * 
     * @param	entity KycRecord
     */
    public KycRecord update( KycRecord entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a KycRecord
	 * 
     * @param	id		UUID
     */
    public KycRecord delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    KycRecord entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Client
     * 
     * @param	parentId	UUID
     * @param	assignment 	Client 
     * @return	KycRecord
     */
    public KycRecord assignClient( UUID parentId, Client assignment ) {
	    LOGGER.info("assigning Client as " + assignment.toString() );

	    KycRecord parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Client.class, assignment.getClientId());

	    // ------------------------------------------
		// assign the Client to the parent entity
		// ------------------------------------------ 
	    parentEntity.setClient( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Client
	 * 
	 * @param	parentId		UUID
	 * @return	KycRecord
	 */
	public KycRecord unAssignClient( UUID parentId ) {
		KycRecord parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Client on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Client on the parent entithy
		// ------------------------------------------     
	    parentEntity.setClient(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Documents
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	KycRecord
     */
    public KycRecord addToDocuments( UUID parentId, Document addTo ) {
	    LOGGER.info("handling AssignDocumentsToKycRecordEvent - " );
	    
	    KycRecord parentEntity = repository.findById(parentId).get();
	    Document child = registry.project( Document.class, addTo.getDocumentId());
	    
	    parentEntity.getDocuments().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Documents
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	KycRecord
     */
	public KycRecord removeFromDocuments( UUID parentId, Document removeFrom ) {
	    LOGGER.info("handling RemoveDocumentsFromKycRecordEvent " );
	
	    KycRecord parentEntity = repository.findById(parentId).get();
	    Document child = registry.project( Document.class, removeFrom.getDocumentId());
	    
	    parentEntity.getDocuments().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the KycRecord via an FindKycRecordQuery
     * @return 	query	FindKycRecordQuery
     */
    @SuppressWarnings("unused")
    public KycRecord find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a KycRecord - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all KycRecords
     *
     * @param	query	FindAllKycRecordQuery 
     * @return 	List<KycRecord> 
     */
    @SuppressWarnings("unused")
    public List<KycRecord> findAll( FindAllKycRecordQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all KycRecord - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final KycRecordRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(KycRecordEntityProjector.class.getName());

}
